style:
.gk-hero {
  background: linear-gradient(135deg, #1B5E20 0%, #2E7D32 55%, #43A047 100%);
  border-radius: 12px;
  padding: 22px 28px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #fff;
  box-shadow: 0 4px 20px rgba(27,94,32,.25);
}
.gk-greeting {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -.2px;
}
.gk-hero-date {
  font-size: 13px;
  margin-top: 4px;
  opacity: .8;
}
.gk-hero-right { text-align: right; }
.gk-hero-company {
  font-size: 13px;
  font-weight: 600;
  opacity: .9;
}
.gk-hero-badge {
  display: inline-block;
  background: rgba(255,255,255,.18);
  border-radius: 20px;
  padding: 2px 11px;
  font-size: 10px;
  letter-spacing: .6px;
  text-transform: uppercase;
  margin-top: 6px;
}
@media (max-width: 576px) {
  .gk-hero { flex-direction: column; align-items: flex-start; gap: 10px; }
  .gk-hero-right { text-align: left; }
}

script:
(function () {
  var h = new Date().getHours();
  var g = h < 12 ? 'Guten Morgen' : h < 18 ? 'Guten Tag' : 'Guten Abend';
  var full = frappe.session.user_fullname || frappe.session.user || '';
  var first = full.split(' ')[0];
  var date = new Intl.DateTimeFormat('de-DE', {
    weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
  }).format(new Date());

  var greetEl = root_element.querySelector('.gk-greeting');
  var dateEl  = root_element.querySelector('.gk-hero-date');
  if (greetEl) greetEl.textContent = g + (first ? ', ' + first : '') + '!';
  if (dateEl)  dateEl.textContent  = date;

  frappe.db.get_single_value('Global Defaults', 'default_company').then(function (c) {
    if (c) {
      var el = root_element.querySelector('.gk-hero-company');
      if (el) el.textContent = c;
    }
  });
})();

style:
.gk-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  padding: 4px 0;
}
.gk-kpi-card {
  background: var(--card-bg, #fff);
  border-radius: 12px;
  padding: 18px 20px;
  box-shadow: 0 1px 8px rgba(0,0,0,.07);
  border-top: 3px solid;
  cursor: pointer;
  transition: transform .15s ease, box-shadow .15s ease;
  position: relative;
  overflow: hidden;
}
.gk-kpi-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 22px rgba(0,0,0,.12);
}
.gk-kpi-card::after {
  content: '';
  position: absolute;
  right: -14px;
  bottom: -14px;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  opacity: .08;
  background: currentColor;
}
.gk-kpi-green  { border-top-color: #22c55e; color: #22c55e; }
.gk-kpi-orange { border-top-color: #f97316; color: #f97316; }
.gk-kpi-violet { border-top-color: #a855f7; color: #a855f7; }
.gk-kpi-blue   { border-top-color: #3b82f6; color: #3b82f6; }
.gk-kpi-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}
.gk-kpi-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .5px;
  color: var(--text-muted, #6b7280);
  font-weight: 600;
}
.gk-kpi-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
.gk-kpi-val {
  font-size: 22px;
  font-weight: 700;
  color: var(--text-color, #111827);
  line-height: 1.15;
  margin-bottom: 5px;
  transition: opacity .3s;
}
.gk-kpi-val.gk-loading { opacity: .35; }
.gk-kpi-sub {
  font-size: 11px;
  color: var(--text-muted, #9ca3af);
}
@media (max-width: 992px) {
  .gk-kpi-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 576px) {
  .gk-kpi-grid { grid-template-columns: 1fr; }
}

script:
(function () {
  function fmt(n) {
    return new Intl.NumberFormat('de-DE', {
      style: 'currency', currency: 'EUR', maximumFractionDigits: 0
    }).format(n);
  }
  function q(sel) { return root_element.querySelector(sel); }
  function setTxt(sel, val) { var e = q(sel); if (e) e.textContent = val; }

  // Show loading state
  ['.gk-val-umsatz', '.gk-val-offen', '.gk-val-pfand', '.gk-val-lieferung'].forEach(function(s) {
    var e = q(s); if (e) e.classList.add('gk-loading');
  });

  frappe.call({
    method: 'getraenkehandel.getraenkehandel.dashboard.get_kpi_stats',
    callback: function (r) {
      ['.gk-val-umsatz', '.gk-val-offen', '.gk-val-pfand', '.gk-val-lieferung'].forEach(function(s) {
        var e = q(s); if (e) e.classList.remove('gk-loading');
      });
      if (!r || !r.message) return;
      var d = r.message;
      setTxt('.gk-val-umsatz',    fmt(d.umsatz_heute));
      setTxt('.gk-val-offen',     d.offene_count + ' Stk');
      setTxt('.gk-sub-offen',     fmt(d.offene_summe) + ' offen');
      setTxt('.gk-val-pfand',     fmt(d.pfand_ausstehend));
      setTxt('.gk-val-lieferung', d.lieferungen_heute + ' Stk');
    }
  });

  var nav = [
    ['.gk-nav-today-si', function() {
      frappe.set_route('List', 'Sales Invoice',
        {posting_date: frappe.datetime.get_today(), docstatus: 1});
    }],
    ['.gk-nav-unpaid', function() {
      frappe.set_route('List', 'Sales Invoice',
        {outstanding_amount: ['>', 0], docstatus: 1});
    }],
    ['.gk-nav-pfand', function() {
      frappe.set_route('query-report', 'Pfand Ledger');
    }],
    ['.gk-nav-today-dn', function() {
      frappe.set_route('List', 'Delivery Note',
        {posting_date: frappe.datetime.get_today()});
    }],
  ];
  nav.forEach(function(pair) {
    var el = q(pair[0]);
    if (el) el.addEventListener('click', pair[1]);
  });
})();
